const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const utah = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Utah'));

  const aug2020 = ee.DateRange('2020-08-01', '2020-08-31');
  const augLongTerm = ee.DateRange('2015-08-01', '2019-08-31');

  // 2. Data Acquisition
  const smap2020 = ee.ImageCollection('NASA/SMAP/SPL3SMP_E/005')
    .filterBounds(utah)
    .filterDate(aug2020)
    .select('soil_moisture_am');

  const smapLongTerm = ee.ImageCollection('NASA/SMAP/SPL3SMP_E/005')
    .filterBounds(utah)
    .filterDate(augLongTerm)
    .select('soil_moisture_am');

  // Check collection sizes
  const count2020 = smap2020.size().getInfo();
  const countLongTerm = smapLongTerm.size().getInfo();

  console.log(`2020 August Images: ${count2020}`);
  console.log(`Long-term August Images: ${countLongTerm}`);

  if (count2020 === 0 || countLongTerm === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create mean composites
  const mean2020 = smap2020.mean();
  const meanLongTerm = smapLongTerm.mean();

  // Check valid pixels
  const count2020Pixels = mean2020.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: utah,
    scale: 3000,
    maxPixels: 1e9
  }).get('soil_moisture_am').getInfo();

  const countLongTermPixels = meanLongTerm.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: utah,
    scale: 3000,
    maxPixels: 1e9
  }).get('soil_moisture_am').getInfo();

  console.log(`2020 Valid Pixels: ${count2020Pixels}`);
  console.log(`Long-term Valid Pixels: ${countLongTermPixels}`);

  if (count2020Pixels === 0 || countLongTermPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation
  const sm2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: utah,
    scale: 3000,
    maxPixels: 1e9
  }).get('soil_moisture_am').getInfo();

  const smLongTerm = meanLongTerm.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: utah,
    scale: 3000,
    maxPixels: 1e9
  }).get('soil_moisture_am').getInfo();

  console.log(`2020 Soil Moisture: ${sm2020 ? sm2020.toFixed(4) : 'null'}`);
  console.log(`Long-term Soil Moisture: ${smLongTerm ? smLongTerm.toFixed(4) : 'null'}`);

  // 5. Validation & Final Answer
  if (sm2020 === null || smLongTerm === null || 
      isNaN(sm2020) || isNaN(smLongTerm) ||
      sm2020 < 0 || sm2020 > 1 || smLongTerm < 0 || smLongTerm > 1) {
    console.log("<answer>C3</answer>");
  } else if (sm2020 < smLongTerm) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
